+// API keys and roles. A key is sent as `Authorization: Bearer <key>` and
+// looked up in the store's `apiKeys`. No business rules here, only who may
+// call which route.
+import { AppError } from "../errors.js";
+
+const RANK = { viewer: 1, cook: 2, manager: 3 };
+
+// Changing routes a cook may call; every other change needs a manager.
+const COOK_ROUTES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** The API key record for a request's headers; throws unauthorized if none. */
+export function authenticate(store, headers) {
+  const header = Object.entries(headers).find(([k]) => k.toLowerCase() === "authorization")?.[1];
+  const key = /^Bearer (.+)$/.exec(String(header ?? ""))?.[1];
+  const found = key && (store.data.apiKeys ?? []).find((k) => k.key === key);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** The role a route needs. */
+export function requiredRole(method, path) {
+  if (path === "/audit") return "manager";
+  if (method === "GET") return "viewer";
+  return COOK_ROUTES.some(([m, re]) => m === method && re.test(path)) ? "cook" : "manager";
+}
+
+/** Throws forbidden unless `role` may call the route. */
+export function authorize(role, method, path) {
+  const need = requiredRole(method, path);
+  if ((RANK[role] ?? 0) < RANK[need]) throw new AppError("forbidden", { role, need });
+}
