+++ b/tests/auth.test.js
@@ -0,0 +1,35 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, bearer } from "./helpers.js";
+
+test("requests without a known key are 401", async () => {
+  const { handle } = app();
+  const none = await handle({ path: "/items", headers: {} });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const bad = await handle({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(bad.status, 401);
+});
+
+test("viewers read, cooks cook, managers do everything", async () => {
+  const { handle } = app();
+  assert.equal((await handle({ path: "/items", headers: bearer("viewer") })).status, 200);
+  const denied = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: bearer("viewer") });
+  assert.equal(denied.status, 403);
+  assert.equal(denied.body.error.code, "forbidden");
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: bearer("cook") })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" }, headers: bearer("cook") })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" }, headers: bearer("manager") })).status, 201);
+});
+
+test("changes are audited and GET /audit is for managers", async () => {
+  const { handle } = app();
+  await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 }, headers: bearer("cook") });
+  await handle({ method: "POST", path: "/orders", body: {}, headers: bearer("viewer") });
+  assert.equal((await handle({ path: "/audit", headers: bearer("cook") })).status, 403);
+  const log = (await handle({ path: "/audit" })).body;
+  assert.equal(log.length, 2);
+  assert.deepEqual(log[0], { at: "2026-10-28T10:00:00.000Z", key: "viewer", method: "POST", path: "/orders", status: 403 });
+  assert.equal(log[1].key, "cook");
+  assert.equal(log[1].status, 200);
+});
